{"action":"write_file","path":"render.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { render } = require('./render');

test('simple substitution', () => {
  assert.equal(render('Hello {{name}}!', { name: 'Ada' }), 'Hello Ada!');
});

test('missing values are empty', () => {
  assert.equal(render('[{{x}}]', {}), '[]');
});

test('spaces inside braces', () => {
  assert.equal(render('{{ name }}', { name: 'Bob' }), 'Bob');
});

test('nested paths and array indexes', () => {
  const data = {
    user: { address: { city: 'Paris' } },
    items: ['apple', 'banana']
  };
  assert.equal(render('{{user.address.city}} - {{items.0}}', data), 'Paris - apple');
});

test('prototype and restricted lookups return empty', () => {
  const data = { name: 'test' };
  assert.equal(render('{{constructor}}', data), '');
  assert.equal(render('{{toString}}', data), '');
  assert.equal(render('{{__proto__}}', data), '');
  assert.equal(render('{{name.length}}', data), '');
  assert.equal(render('{{a..b}}', data), '');
});

test('null and undefined render as empty', () => {
  assert.equal(render('{{a}}', { a: null }), '');
  assert.equal(render('{{a}}', { a: undefined }), '');
});

test('primitive conversions (0 and false)', () => {
  assert.equal(render('{{zero}} {{bool}}', { zero: 0, bool: false }), '0 false');
});

test('HTML escaping in double braces', () => {
  assert.equal(render('{{html}}', { html: '<script>&"'</script>' }), '&lt;script&gt;&amp;&quot;&#39;&lt;/script&gt;');
});

test('triple braces unescaped', () => {
  assert.equal(render('{{{html}}}', { html: '<b>bold</b>' }), '<b>bold</b>');
});

test('escaped tags with backslash', () => {
  assert.equal(render('\\{{name}}', { name: 'Ada' }), '{{name}}');
  assert.equal(render('\\{{{name}}}', { name: 'Ada' }), '{{{name}}}');
});

test('invalid tags stay as written', () => {
  assert.equal(render('{{ name', {}), '{{ name');
  assert.equal(render('{{ a b }}', {}), '{{ a b }}');
  assert.equal(render('{{}}', {}), '{{}}');
});

test('type checks throw TypeError', () => {
  assert.throws(() => render(123, {}), TypeError);
  assert.throws(() => render('template', null), TypeError);
  assert.throws(() => render('template', undefined), TypeError);
  assert.throws(() => render('template', 'not an object'), TypeError);
});
"}```

